import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.util.MembershipLevel;

/**
 * Emits an audit trail line to the dedicated {@code AUDIT} logger once a new owner has been
 * persisted. Runs after {@link SaveOwner} so the generated id is available, and carries the
 * owner id, the assigned {@code customerCode}, the {@code registrationDate} and the derived
 * {@code membershipLevel}.
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int points = MembershipLevel.pointsOf(owner, Household.memberCount(owner, ownerRepository));
        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                MembershipLevel.levelOf(points));
    }
}

